# Loaders for the example datasets in data/.
# Pages load this with: source(here::here("R/data.R"))
#
# Add a loader here rather than reading files directly in a page, so a dataset
# used by several pages stays consistent.

#' Simulated coastal shelf survey.
#'
#' One row per survey station: where it was, what the water was like, and how many
#' individuals of one benthic species were caught.
#'
#' SIMULATED data, generated by R/make-example-data.R. Any page using it must say
#' so. The true relationships are documented at the top of that script.
load_coastal_survey <- function() {
  readr::read_csv(
    here::here("data", "coastal-survey.csv"),
    col_types = readr::cols(
      station_id        = readr::col_character(),
      survey_year       = readr::col_integer(),
      season            = readr::col_factor(c("spring", "summer", "autumn", "winter")),
      longitude         = readr::col_double(),
      latitude          = readr::col_double(),
      depth_m           = readr::col_double(),
      temperature_c     = readr::col_double(),
      salinity_psu      = readr::col_double(),
      chlorophyll_mg_m3 = readr::col_double(),
      substrate         = readr::col_factor(c("sand", "mud", "gravel", "rock")),
      abundance         = readr::col_integer(),
      present           = readr::col_factor(c("yes", "no"))
    )
  )
}

#' The same survey, as it came off the ship.
#'
#' 815 rows: the 800 station visits in `load_coastal_survey()` plus 15 duplicated
#' rows, with realistic damage and several extra columns. Read deliberately without
#' cleaning — sentinel values, inconsistent labels and text dates all arrive as they
#' are, because section 2 is about finding and fixing them.
#'
#' SIMULATED data, generated by R/make-raw-data.R from the clean extract.
load_coastal_survey_raw <- function() {
  readr::read_csv(
    here::here("data", "coastal-survey-raw.csv"),
    col_types = readr::cols(.default = readr::col_character()),
    na = character()
  ) |>
    readr::type_convert(col_types = readr::cols(
      survey_year       = readr::col_integer(),
      longitude         = readr::col_double(),
      latitude          = readr::col_double(),
      depth_m           = readr::col_double(),
      temperature_c     = readr::col_double(),
      salinity_psu      = readr::col_double(),
      chlorophyll_mg_m3 = readr::col_double(),
      abundance         = readr::col_integer(),
      catch_weight_kg   = readr::col_double(),
      .default          = readr::col_character()
    ))
}
